package com.example.blobevents;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

public final class AsyncEventReceiver {
    private static final Logger LOGGER = LoggerFactory.getLogger(AsyncEventReceiver.class);
    private final BlobEventHandler handler;

    public AsyncEventReceiver(BlobEventHandler handler) {
        this.handler = handler;
    }

    public Flux<EventEnvelope> receive(String jsonPayload) {
        return Flux.fromIterable(EventPayloadParser.parse(jsonPayload))
                .concatMap(event -> route(event).thenReturn(event));
    }

    private Mono<Void> route(EventEnvelope event) {
        return switch (event.type()) {
            case EventReceiver.BLOB_CREATED -> handler.handleCreatedAsync(event);
            case EventReceiver.BLOB_DELETED -> handler.handleDeletedAsync(event);
            default -> {
                LOGGER.warn("Ignoring unrecognized event type {} for event {}", event.type(), event.id());
                yield Mono.empty();
            }
        };
    }
}

package com.example.blobevents;

import com.azure.core.util.BinaryData;
import com.azure.storage.blob.BlobAsyncClient;
import com.azure.storage.blob.BlobClient;
import com.azure.storage.blob.BlobServiceAsyncClient;
import com.azure.storage.blob.BlobServiceClient;
import com.azure.storage.blob.models.BlobProperties;
import com.azure.storage.blob.models.BlobStorageException;
import reactor.core.publisher.Mono;

import static com.example.blobevents.BlobEventHandler.BlobAddress;
import static com.example.blobevents.BlobEventHandler.BlobSummary;
import static com.example.blobevents.BlobEventHandler.BlobUnavailableException;

public final class AzureBlobOperations
        implements BlobEventHandler.BlobOperations, BlobEventHandler.AsyncBlobOperations {

    private final BlobServiceClient syncClient;
    private final BlobServiceAsyncClient asyncClient;

    public AzureBlobOperations(BlobServiceClient syncClient, BlobServiceAsyncClient asyncClient) {
        this.syncClient = syncClient;
        this.asyncClient = asyncClient;
    }

    @Override
    public BlobSummary download(BlobAddress address) {
        BlobClient blob = syncClient.getBlobContainerClient(address.container()).getBlobClient(address.name());
        try {
            BlobProperties properties = blob.getProperties();
            BinaryData content = blob.downloadContent();
            return toSummary(address, properties, content.getLength());
        } catch (BlobStorageException exception) {
            throw translate(exception);
        }
    }

    @Override
    public Mono<BlobSummary> downloadAsync(BlobAddress address) {
        BlobAsyncClient blob = asyncClient.getBlobContainerAsyncClient(address.container())
                .getBlobAsyncClient(address.name());
        return blob.getProperties()
                .flatMap(properties -> blob.downloadContent()
                        .map(content -> toSummary(address, properties, content.getLength())))
                .onErrorMap(BlobStorageException.class, this::translate);
    }

    private BlobSummary toSummary(BlobAddress address, BlobProperties properties, long downloadedSize) {
        String tier = properties.getAccessTier() == null ? "unknown" : properties.getAccessTier().toString();
        return new BlobSummary(address.name(), downloadedSize, properties.getContentType(), tier);
    }

    private BlobUnavailableException translate(BlobStorageException exception) {
        String errorCode = exception.getErrorCode() == null ? "unknown" : exception.getErrorCode().toString();
        if (exception.getStatusCode() == 404) {
            return new BlobUnavailableException("the blob was deleted or moved (HTTP 404)", exception);
        }
        if ("BlobArchived".equalsIgnoreCase(errorCode)) {
            return new BlobUnavailableException("the blob is in the archive tier", exception);
        }
        throw exception;
    }
}

package com.example.blobevents;

import com.azure.core.credential.TokenCredential;
import com.azure.identity.DefaultAzureCredentialBuilder;
import com.azure.storage.blob.BlobServiceAsyncClient;
import com.azure.storage.blob.BlobServiceClient;
import com.azure.storage.blob.BlobServiceClientBuilder;

public final class AzureConfiguration {
    private final TokenCredential credential;
    private final BlobServiceClient blobServiceClient;
    private final BlobServiceAsyncClient blobServiceAsyncClient;

    public AzureConfiguration(String storageAccountEndpoint) {
        this.credential = new DefaultAzureCredentialBuilder().build();
        BlobServiceClientBuilder builder = new BlobServiceClientBuilder()
                .endpoint(requireHttps(storageAccountEndpoint))
                .credential(credential);
        this.blobServiceClient = builder.buildClient();
        this.blobServiceAsyncClient = builder.buildAsyncClient();
    }

    public BlobEventHandler blobEventHandler() {
        AzureBlobOperations operations = new AzureBlobOperations(blobServiceClient, blobServiceAsyncClient);
        return new BlobEventHandler(operations, operations);
    }

    public EventPublisher eventPublisher(String topicEndpoint) {
        return new EventPublisher(topicEndpoint, credential);
    }

    public AsyncEventPublisher asyncEventPublisher(String topicEndpoint) {
        return new AsyncEventPublisher(topicEndpoint, credential);
    }

    private static String requireHttps(String endpoint) {
        if (endpoint == null || !endpoint.startsWith("https://")) {
            throw new IllegalArgumentException("Azure Storage endpoint must use HTTPS");
        }
        return endpoint;
    }
}

package com.example.blobevents;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import reactor.core.publisher.Mono;

import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;

public final class BlobEventHandler {
    private static final Logger LOGGER = LoggerFactory.getLogger(BlobEventHandler.class);
    private static final String SUBJECT_PREFIX = "/blobServices/default/containers/";
    private static final String BLOB_SEPARATOR = "/blobs/";

    private final BlobOperations blobOperations;
    private final AsyncBlobOperations asyncBlobOperations;

    public BlobEventHandler(BlobOperations blobOperations, AsyncBlobOperations asyncBlobOperations) {
        this.blobOperations = blobOperations;
        this.asyncBlobOperations = asyncBlobOperations;
    }

    public void handleCreated(EventEnvelope event) {
        BlobAddress address = parseSubject(event.subject());
        try {
            logSummary(blobOperations.download(address));
        } catch (BlobUnavailableException exception) {
            LOGGER.warn("Blob {} in container {} is no longer readable: {}",
                    address.name(), address.container(), exception.getMessage());
        }
    }

    public Mono<Void> handleCreatedAsync(EventEnvelope event) {
        BlobAddress address = parseSubject(event.subject());
        return asyncBlobOperations.downloadAsync(address)
                .doOnNext(this::logSummary)
                .onErrorResume(BlobUnavailableException.class, exception -> {
                    LOGGER.warn("Blob {} in container {} is no longer readable: {}",
                            address.name(), address.container(), exception.getMessage());
                    return Mono.empty();
                })
                .then();
    }

    public void handleDeleted(EventEnvelope event) {
        BlobAddress address = parseSubject(event.subject());
        LOGGER.info("Blob deleted: container={}, name={}", address.container(), address.name());
    }

    public Mono<Void> handleDeletedAsync(EventEnvelope event) {
        handleDeleted(event);
        return Mono.empty();
    }

    static BlobAddress parseSubject(String subject) {
        if (subject == null || !subject.startsWith(SUBJECT_PREFIX)) {
            throw new IllegalArgumentException("Unexpected blob event subject: " + subject);
        }

        int blobSeparator = subject.indexOf(BLOB_SEPARATOR, SUBJECT_PREFIX.length());
        if (blobSeparator < 0) {
            throw new IllegalArgumentException("Blob event subject has no blob name: " + subject);
        }

        String container = subject.substring(SUBJECT_PREFIX.length(), blobSeparator);
        String name = subject.substring(blobSeparator + BLOB_SEPARATOR.length());
        if (container.isBlank() || name.isBlank()) {
            throw new IllegalArgumentException("Blob event subject has an empty container or blob name: " + subject);
        }
        return new BlobAddress(decode(container), decode(name));
    }

    private static String decode(String value) {
        return URLDecoder.decode(value.replace("+", "%2B"), StandardCharsets.UTF_8);
    }

    private void logSummary(BlobSummary summary) {
        LOGGER.info("Blob created: name={}, size={} bytes, contentType={}, accessTier={}",
                summary.name(), summary.size(), summary.contentType(), summary.accessTier());
    }

    @FunctionalInterface
    public interface BlobOperations {
        BlobSummary download(BlobAddress address);
    }

    @FunctionalInterface
    public interface AsyncBlobOperations {
        Mono<BlobSummary> downloadAsync(BlobAddress address);
    }

    public record BlobAddress(String container, String name) {
    }

    public record BlobSummary(String name, long size, String contentType, String accessTier) {
    }

    public static final class BlobUnavailableException extends RuntimeException {
        public BlobUnavailableException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}

