package com.example.blobevents;

import com.azure.core.models.CloudEvent;
import com.azure.messaging.eventgrid.EventGridEvent;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public final class EventPayloadParser {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();

    private EventPayloadParser() {
    }

    public static List<EventEnvelope> parse(String payload) {
        try {
            JsonNode root = OBJECT_MAPPER.readTree(payload);
            List<JsonNode> nodes = new ArrayList<>();
            if (root.isArray()) {
                root.forEach(nodes::add);
            } else if (root.isObject()) {
                nodes.add(root);
            } else {
                throw new IllegalArgumentException("Event payload must be a JSON object or array");
            }

            List<EventEnvelope> events = new ArrayList<>(nodes.size());
            for (JsonNode node : nodes) {
                events.add(node.hasNonNull("specversion")
                        ? fromCloudEvent(node)
                        : fromEventGridEvent(node));
            }
            return List.copyOf(events);
        } catch (IOException | RuntimeException exception) {
            throw new IllegalArgumentException("Invalid Event Grid webhook payload", exception);
        }
    }

    private static EventEnvelope fromEventGridEvent(JsonNode node) {
        EventGridEvent event = EventGridEvent.fromString(node.toString()).get(0);
        return new EventEnvelope(
                event.getId(),
                event.getEventType(),
                event.getSubject(),
                event.getEventTime(),
                event.getData(),
                EventEnvelope.Schema.EVENT_GRID);
    }

    private static EventEnvelope fromCloudEvent(JsonNode node) {
        CloudEvent event = CloudEvent.fromString(node.toString()).get(0);
        return new EventEnvelope(
                event.getId(),
                event.getType(),
                event.getSubject(),
                event.getTime(),
                event.getData(),
                EventEnvelope.Schema.CLOUD_EVENTS);
    }
}

package com.example.blobevents;

import com.azure.core.credential.TokenCredential;
import com.azure.core.util.BinaryData;
import com.azure.messaging.eventgrid.EventGridEvent;
import com.azure.messaging.eventgrid.EventGridPublisherClient;
import com.azure.messaging.eventgrid.EventGridPublisherClientBuilder;

import java.util.List;
import java.util.function.Consumer;

public final class EventPublisher {
    private final Consumer<List<EventGridEvent>> sender;

    public EventPublisher(String topicEndpoint, TokenCredential credential) {
        EventGridPublisherClient<EventGridEvent> client = new EventGridPublisherClientBuilder()
                .endpoint(requireHttps(topicEndpoint))
                .credential(credential)
                .buildEventGridEventPublisherClient();
        this.sender = client::sendEvents;
    }

    EventPublisher(Consumer<List<EventGridEvent>> sender) {
        this.sender = sender;
    }

    public void publish(List<CustomEvent> customEvents) {
        sender.accept(toEventGridEvents(customEvents));
    }

    static List<EventGridEvent> toEventGridEvents(List<CustomEvent> customEvents) {
        return customEvents.stream()
                .map(event -> new EventGridEvent(
                        event.subject(),
                        event.eventType(),
                        BinaryData.fromObject(event.data()),
                        "1.0"))
                .toList();
    }

    static String requireHttps(String endpoint) {
        if (endpoint == null || !endpoint.startsWith("https://")) {
            throw new IllegalArgumentException("Event Grid topic endpoint must use HTTPS");
        }
        return endpoint;
    }
}

package com.example.blobevents;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.List;

public final class EventReceiver {
    public static final String BLOB_CREATED = "Microsoft.Storage.BlobCreated";
    public static final String BLOB_DELETED = "Microsoft.Storage.BlobDeleted";

    private static final Logger LOGGER = LoggerFactory.getLogger(EventReceiver.class);
    private final BlobEventHandler handler;

    public EventReceiver(BlobEventHandler handler) {
        this.handler = handler;
    }

    public List<EventEnvelope> receive(String jsonPayload) {
        List<EventEnvelope> events = EventPayloadParser.parse(jsonPayload);
        events.forEach(this::route);
        return events;
    }

    private void route(EventEnvelope event) {
        switch (event.type()) {
            case BLOB_CREATED -> handler.handleCreated(event);
            case BLOB_DELETED -> handler.handleDeleted(event);
            default -> LOGGER.warn("Ignoring unrecognized event type {} for event {}", event.type(), event.id());
        }
    }
}

